// ============ CONFIGURACIÓN DEL CLIENTE (edita solo este bloque) ============
const CONFIG_BASE = {
  tienda: 'Tienda Demo',
  fuente: 'demo',                 // 'demo', 'woocommerce' o 'web'
  woo_url: '',                    // si fuente = 'woocommerce': https://tu-tienda.com (usa su API con tu credencial)

  // Con fuente = 'web': páginas públicas de opiniones, cada una con sus selectores CSS
  // (se sacan con el inspector del navegador: clic derecho → Inspeccionar).
  // Antes de leer cada página se comprueba su robots.txt: si no permite la lectura
  // automática, el workflow se para y lo dice. Trustpilot, por ejemplo, no la permite.
  // Las reseñas de Google Maps se cargan con JavaScript y así no se leen: para esas está la API de Google Business Profile.
  sitios: [
    // {
    //   nombre: 'Opiniones de mi web',
    //   url: 'https://mi-tienda.com/opiniones',
    //   bloque: '.opinion',
    //   texto: '.opinion-texto',
    //   puntuacion: '.opinion-estrellas',
    //   puntuacion_attr: 'data-nota',
    //   autor: '.opinion-autor',
    //   fecha: 'time',
    //   fecha_attr: 'datetime',
    // },
  ],

  umbral_negativa: 3,             // puntuación (sobre 5) que se considera una queja
  avisar_solo_nuevas: true,       // no repetir avisos de reseñas ya vistas
  max_por_aviso: 10,              // tope de reseñas por aviso, para no mandar un tocho

  email_to: 'cliente@ejemplo.com',
  email_from: 'resenas@tu-dominio.com',
  telegram_chat_id: 'TU_CHAT_ID',
};
// ============================================================================

// ---- Panel único de Denoro: los ajustes del cliente llegan en la entrada ----
const __ENTRADA = $input.first().json || {};
const __limpio = (o) => Object.fromEntries(Object.entries(o || {}).filter(([, x]) => x !== '' && x !== null && x !== undefined));
const __mezclar = (b, o) => {
  const r = { ...b };
  for (const [k, v] of Object.entries(o || {})) {
    if (v && typeof v === 'object' && !Array.isArray(v) && b[k] && typeof b[k] === 'object' && !Array.isArray(b[k])) r[k] = { ...b[k], ...__limpio(v) };
    else if (v !== undefined && v !== null) r[k] = v;
  }
  return r;
};
const CONFIG = { ...__mezclar(CONFIG_BASE, __ENTRADA.config), __token: String(__ENTRADA.token || ''), __auto: String(__ENTRADA.auto || ''), __clave: String(__ENTRADA.clave || '') };
if (!CONFIG.__token || !CONFIG.__clave) throw new Error('Esta versión se lanza desde el panel de Denoro (falta el cliente)');
if (!['demo', 'woocommerce', 'web'].includes(CONFIG.fuente)) throw new Error(`fuente "${CONFIG.fuente}" no válida: usa demo, woocommerce o web`);
if (CONFIG.fuente === 'woocommerce' && !/^https?:\/\/[^/]+/i.test(String(CONFIG.woo_url || ''))) {
  throw new Error('Con fuente = woocommerce hace falta woo_url: la dirección de la tienda (https://tu-tienda.com)');
}
if (CONFIG.fuente === 'web') {
  if (!Array.isArray(CONFIG.sitios) || !CONFIG.sitios.length) {
    throw new Error('Con fuente = web hay que definir al menos un sitio en "sitios"');
  }
  CONFIG.sitios.forEach((s, i) => {
    for (const campo of ['nombre', 'url', 'bloque', 'texto']) {
      if (!String(s[campo] || '').trim()) throw new Error(`Al sitio ${i + 1} le falta "${campo}"`);
    }
    if (!/^https?:\/\//i.test(s.url)) throw new Error(`La url del sitio "${s.nombre}" tiene que empezar por http:// o https://`);
  });
}
if (!(CONFIG.umbral_negativa >= 1 && CONFIG.umbral_negativa <= 5)) {
  throw new Error('umbral_negativa debe estar entre 1 y 5');
}
if (!(CONFIG.max_por_aviso >= 1 && CONFIG.max_por_aviso <= 100)) throw new Error('max_por_aviso debe estar entre 1 y 100');
const PLACEHOLDER = /ejemplo\.com|tu-dominio|TU_CHAT_ID/i;
for (const k of ['email_to', 'email_from', 'telegram_chat_id']) {
  if (PLACEHOLDER.test(String(CONFIG[k] || ''))) {
    throw new Error(`Configura "${k}" en el nodo Configuración (ahora tiene un valor de ejemplo). Déjalo vacío ('') para desactivar ese canal.`);
  }
}
if (CONFIG.telegram_chat_id && !/^-?\d+$|^@\w+$/.test(String(CONFIG.telegram_chat_id))) {
  throw new Error('telegram_chat_id debe ser un número (p. ej. 123456789) o @canal');
}
if (!CONFIG.email_to && !CONFIG.telegram_chat_id) throw new Error('Configura al menos un canal: email_to o telegram_chat_id');
if (CONFIG.email_to && !CONFIG.email_from) throw new Error('Falta email_from (la cuenta SMTP que envía)');

const modo = $input.first().json.modo === 'resumen' ? 'resumen' : 'vigilancia';
return [{ json: {
  ...CONFIG,
  modo,
  woo_url: String(CONFIG.woo_url || '').replace(/\/+$/, ''),
  enviar_email: Boolean(CONFIG.email_to),
  enviar_telegram: Boolean(CONFIG.telegram_chat_id),
  ahora: new Date().toISOString(),
} }];

// Reseñas de ejemplo repartidas en el tiempo, con quejas repetidas sobre el mismo tema
// (el plazo de envío), que es justo lo que el resumen tiene que hacer visible.
const cfg = $('Configuración').first().json;
const ahora = new Date(cfg.ahora).getTime();
const hace = (d) => new Date(ahora - d * 86400000).toISOString();
const R = (sitio, autor, puntuacion, dias, texto) => ({ json: {
  sitio, autor, puntuacion, fecha: hace(dias), texto, url: 'https://tienda-demo.test/opiniones#' + autor.toLowerCase(),
} });

return [
  R('Tu tienda', 'Marta', 5, 0.2, 'La mesa llegó perfecta y el montaje fue sencillo. Repetiré sin duda.'),
  R('Tu tienda', 'Javier', 2, 0.5, 'El pedido tardó tres semanas en llegar. El producto bien, pero el plazo de envío es inaceptable.'),
  R('Tu tienda', 'Lucía', 1, 1, 'Sigo esperando mi pedido. Nadie contesta al correo de atención al cliente.'),
  R('Tu tienda', 'Pablo', 4, 2, 'Buena calidad por el precio. El envío tardó algo más de lo previsto.'),
  R('Web de opiniones', 'Ana', 5, 3, 'Atención impecable, me resolvieron una duda por teléfono en dos minutos.'),
  R('Web de opiniones', 'Sergio', 2, 4, 'Producto correcto pero el envío se retrasó una semana sin avisar.'),
  R('Web de opiniones', 'Elena', 5, 5, 'Encantada con la lámpara, se ve mejor que en las fotos.'),
  R('Tu tienda', 'Rubén', 3, 6, 'Cumple. Nada especial, el embalaje llegó algo dañado.'),
  R('Web de opiniones', 'Nuria', 5, 8, 'Segunda compra y todo perfecto otra vez.'),
  R('Tu tienda', 'Iván', 1, 9, 'Devolución imposible. Llevo dos semanas persiguiendo el reembolso.'),
  R('Web de opiniones', 'Carmen', 4, 11, 'Muy contenta con la compra, el envío fue rápido esta vez.'),
  R('Tu tienda', 'Óscar', 5, 13, 'Excelente calidad de los materiales y buen precio.'),
];

// Un item por sitio a vigilar, con su URL y sus selectores.
const cfg = $('Configuración').first().json;
return cfg.sitios.map((s) => ({ json: {
  nombre: s.nombre,
  url: s.url,
  robots_url: s.url.match(/^https?:\/\/[^/?#]+/i)[0] + '/robots.txt',
  ruta: (s.url.replace(/^https?:\/\/[^/?#]+/i, '') || '/'),
  sel: {
    bloque: s.bloque,
    texto: s.texto,
    puntuacion: s.puntuacion || '',
    puntuacion_attr: s.puntuacion_attr || '',
    autor: s.autor || '',
    fecha: s.fecha || '',
    fecha_attr: s.fecha_attr || '',
  },
} }));

// Antes de leer ninguna página, mira su robots.txt. Si no permite la lectura automática
// a este bot (o a cualquiera), el workflow se para y dice qué sitio quitar de la lista.
const sitios = $('Preparar sitios').all().map((i) => i.json);
const respuestas = $input.all().map((i) => i.json || {});
const BOT = 'denorobot';

// Convierte un patrón de robots.txt (con * y $) en una expresión regular.
const aRegex = (p) => {
  const fin = p.endsWith('$');
  const cuerpo = (fin ? p.slice(0, -1) : p).split('*').map((s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('.*');
  return new RegExp('^' + cuerpo + (fin ? '$' : ''));
};

const permitido = (texto, ruta) => {
  const grupos = [];
  let actual = null;
  let leyendoAgentes = false;
  for (const bruta of String(texto || '').split(/\r?\n/)) {
    const linea = bruta.replace(/#.*/, '').trim();
    const m = linea.match(/^([A-Za-z-]+)\s*:\s*(.*)$/);
    if (!m) continue;
    const clave = m[1].toLowerCase();
    const valor = m[2].trim();
    if (clave === 'user-agent') {
      if (!actual || !leyendoAgentes) { actual = { agentes: [], reglas: [] }; grupos.push(actual); }
      actual.agentes.push(valor.toLowerCase());
      leyendoAgentes = true;
    } else if (clave === 'allow' || clave === 'disallow') {
      leyendoAgentes = false;
      if (actual && valor) actual.reglas.push({ permite: clave === 'allow', patron: valor });
    } else {
      leyendoAgentes = false;
    }
  }
  // Manda el grupo que nombra a este bot; si no hay, el de "*".
  const propios = grupos.filter((g) => g.agentes.some((a) => a !== '*' && BOT.includes(a)));
  const aplicables = propios.length ? propios : grupos.filter((g) => g.agentes.includes('*'));
  let mejor = null;
  for (const r of aplicables.flatMap((g) => g.reglas)) {
    if (!aRegex(r.patron).test(ruta)) continue;
    // La regla más específica (más larga) gana; en empate, gana la que permite.
    if (!mejor || r.patron.length > mejor.patron.length || (r.patron.length === mejor.patron.length && r.permite)) mejor = r;
  }
  return mejor ? mejor.permite : true;
};

const bloqueados = [];
const dudosos = [];
sitios.forEach((s, i) => {
  const r = respuestas[i] || {};
  const estado = Number(r.statusCode || r.status || 0);
  const cuerpo = r.body ?? r.data ?? '';
  if (estado >= 500 || (!estado && r.error)) { dudosos.push(s.nombre); return; }
  // 4xx (sin robots.txt, o no accesible): por convención se entiende que no hay restricciones.
  if (estado >= 400) return;
  if (!permitido(cuerpo, s.ruta)) bloqueados.push(`${s.nombre} (${s.url})`);
});
if (bloqueados.length) {
  throw new Error(`Estos sitios no permiten la lectura automática según su robots.txt: ${bloqueados.join(', ')}. Quítalos de "sitios" en el nodo Configuración.`);
}
if (dudosos.length) {
  throw new Error(`No se ha podido comprobar el robots.txt de: ${dudosos.join(', ')}. Se reintentará en la próxima pasada.`);
}
return sitios.map((s) => ({ json: s }));

// Convierte lo que saca el nodo de extracción HTML en reseñas con la misma forma que el modo demo.
const cfg = $('Configuración').first().json;
const limpiar = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();
// "Valorado con 2 de 5 estrellas" / "2,0" / "★★☆☆☆" -> 2
const puntuacionDe = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const s = String(v);
  const estrellas = (s.match(/[★●]/g) || []).length;
  if (estrellas >= 1 && estrellas <= 5) return estrellas;
  const m = s.match(/(\d(?:[.,]\d)?)\s*(?:\/|de\s+|out of\s+)?\s*5?/);
  if (!m) return null;
  const n = parseFloat(m[1].replace(',', '.'));
  return n >= 0 && n <= 5 ? Math.round(n) : null;
};
const fechaDe = (v) => {
  if (!v) return null;
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
};

// El nodo HTTP sustituye el item por la página: el nombre y la URL del sitio se recuperan
// del nodo que decidió qué leer (mismo orden de items).
let sitios = [];
try { sitios = $('Comprobar robots.txt').all().map((i) => i.json); } catch (e) { sitios = []; }
const salida = [];
$input.all().forEach((item, idx) => {
  const j = { ...(sitios[idx] || {}), ...item.json };
  const nombre = j.sitio || j.nombre || 'web';
  const textos = [].concat(j.texto || []);
  const autores = [].concat(j.autor || []);
  const puntos = [].concat(j.puntuacion || []);
  const fechas = [].concat(j.fecha || []);
  if (!textos.length) return;
  textos.forEach((t, i) => {
    const texto = limpiar(t);
    if (texto.length < 3) return;
    salida.push({ json: {
      sitio: nombre,
      autor: limpiar(autores[i]) || 'anónimo',
      puntuacion: puntuacionDe(puntos[i]),
      fecha: fechaDe(fechas[i]) || cfg.ahora,
      texto,
      url: j.url || '',
    } });
  });
});
if (!salida.length) {
  throw new Error('No se extrajo ninguna reseña: revisa los selectores CSS (la página puede haber cambiado su maquetación)');
}
return salida;

// Reseñas de la propia tienda WooCommerce, leídas con su API oficial y la credencial del cliente.
// El email del autor que devuelve la API no se usa ni se guarda.
const cfg = $('Configuración').first().json;
const limpiar = (s) => String(s ?? '').replace(/<[^>]*>/g, ' ').replace(/&[a-z#0-9]+;/gi, ' ').replace(/\s+/g, ' ').trim();
const salida = [];
for (const item of $input.all()) {
  const r = item.json;
  if (!r || !r.id || r.status && r.status !== 'approved') continue;
  const texto = limpiar(r.review);
  if (!texto) continue;
  const nota = Number(r.rating);
  salida.push({ json: {
    sitio: 'Tu tienda',
    autor: limpiar(r.reviewer) || 'anónimo',
    puntuacion: nota >= 1 && nota <= 5 ? Math.round(nota) : null,
    fecha: r.date_created_gmt ? `${r.date_created_gmt}Z`.replace(/ZZ$/, 'Z') : (r.date_created || cfg.ahora),
    texto: r.product_name ? `${texto} (sobre «${limpiar(r.product_name)}»)` : texto,
    url: r.product_permalink ? `${r.product_permalink}#reviews` : `${cfg.woo_url}/wp-admin/edit.php?post_type=product&page=product-reviews`,
  } });
}
if (!salida.length) throw new Error('WooCommerce no devolvió reseñas aprobadas: revisa la credencial y que la tienda tenga reseñas');
return salida;

const __estadoCliente = () => { const g = $getWorkflowStaticData('global'); const k = String($('Configuración').first().json.__token || '_'); g.clientes = g.clientes || {}; return (g.clientes[k] = g.clientes[k] || {}); };
// Clasifica las reseñas, se queda con las que no se habían visto y agrupa las quejas por tema.
const cfg = $('Configuración').first().json;
const estado = __estadoCliente();
estado.vistas = estado.vistas || {};
estado.semanas = estado.semanas || [];

const ahora = new Date(cfg.ahora).getTime();
const resenas = $input.all().map((i) => i.json).filter((r) => r && r.texto);
if (!resenas.length) throw new Error('No llegó ninguna reseña');

// huella corta y estable para no repetir avisos (no se guarda el texto entero)
const huella = (r) => {
  const base = `${r.sitio}|${r.autor}|${String(r.texto).slice(0, 80)}`;
  let h = 5381;
  for (let i = 0; i < base.length; i++) h = ((h * 33) ^ base.charCodeAt(i)) >>> 0;
  return h.toString(36);
};

const sinTildes = (s) => String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const NEGATIVAS = ['tarde', 'tardo', 'retraso', 'nunca llego', 'no llego', 'roto', 'danado', 'defectuoso',
  'imposible', 'pesimo', 'horrible', 'estafa', 'no contesta', 'sin avisar', 'esperando', 'inaceptable',
  'lamentable', 'decepcion', 'mala experiencia', 'no recomiendo'];
const POSITIVAS = ['perfecto', 'perfecta', 'excelente', 'impecable', 'rapido', 'rapida', 'encantad',
  'recomiendo', 'repetire', 'genial', 'buena calidad', 'contenta', 'contento', 'fantastic', 'muy bien'];
const TEMAS = {
  'Plazos de envío': ['envio', 'envío', 'tardo', 'tarde', 'retraso', 'plazo', 'llego', 'esperando', 'semanas', 'dias'],
  'Atención al cliente': ['atencion', 'contesta', 'respuesta', 'telefono', 'correo', 'soporte', 'nadie', 'ignoran'],
  'Devoluciones y reembolsos': ['devolucion', 'reembolso', 'cambio', 'garantia', 'devolver'],
  'Estado del producto': ['roto', 'danado', 'defectuoso', 'embalaje', 'golpe', 'falta', 'incompleto'],
  'Precio': ['precio', 'caro', 'coste', 'cobrado'],
};

// Solo para reseñas sin estrellas: cuando hay nota, manda la nota.
const porPalabras = (r) => {
  const t = sinTildes(r.texto);
  const neg = NEGATIVAS.filter((p) => t.includes(p)).length;
  const pos = POSITIVAS.filter((p) => t.includes(p)).length;
  if (neg > pos) return 'negativa';
  if (pos > neg) return 'positiva';
  return 'neutra';
};

const marcadas = resenas.map((r) => {
  const h = huella(r);
  const vistasSitio = estado.vistas[r.sitio] || [];
  // Con umbral 3, un 3 es "regular" (neutra) y el 1 y el 2 son quejas.
  const sentimiento = (r.puntuacion === null || r.puntuacion === undefined) ? porPalabras(r)
    : (r.puntuacion < cfg.umbral_negativa ? 'negativa'
      : (r.puntuacion === cfg.umbral_negativa ? 'neutra' : 'positiva'));
  return { ...r, huella: h, nueva: !vistasSitio.includes(h), sentimiento };
});

const nuevas = marcadas.filter((r) => r.nueva);
const paraAvisar = (cfg.avisar_solo_nuevas ? nuevas : marcadas)
  .filter((r) => r.sentimiento === 'negativa')
  .sort((a, b) => (a.puntuacion ?? 9) - (b.puntuacion ?? 9))
  .slice(0, cfg.max_por_aviso);

// --- estadísticas de los últimos 7 días, para el resumen semanal ---
const semana = marcadas.filter((r) => ahora - Date.parse(r.fecha) <= 7 * 86400000);
const conNota = semana.filter((r) => typeof r.puntuacion === 'number');
const media = conNota.length ? Math.round((conNota.reduce((s, r) => s + r.puntuacion, 0) / conNota.length) * 10) / 10 : null;
const estrellas = [1, 2, 3, 4, 5].map((n) => ({ estrellas: n, total: conNota.filter((r) => r.puntuacion === n).length }));
const porSitio = {};
for (const r of semana) porSitio[r.sitio] = (porSitio[r.sitio] || 0) + 1;

const quejas = semana.filter((r) => r.sentimiento === 'negativa');
const temas = Object.entries(TEMAS).map(([tema, palabras]) => ({
  tema,
  total: quejas.filter((r) => palabras.some((p) => sinTildes(r.texto).includes(sinTildes(p)))).length,
})).filter((t) => t.total > 0).sort((a, b) => b.total - a.total);

const anterior = estado.semanas[estado.semanas.length - 1] || null;
const tendencia = anterior && media !== null && anterior.media !== null
  ? { media: Math.round((media - anterior.media) * 10) / 10, total: semana.length - anterior.total }
  : null;

// --- se guarda lo visto (acotado, para que el estado no crezca sin fin) ---
for (const r of marcadas) {
  const lista = estado.vistas[r.sitio] || [];
  if (!lista.includes(r.huella)) lista.push(r.huella);
  estado.vistas[r.sitio] = lista.slice(-800);
}
if (cfg.modo === 'resumen') {
  estado.semanas.push({ hasta: cfg.ahora, total: semana.length, media, negativas: quejas.length });
  estado.semanas = estado.semanas.slice(-12);
}

return [{ json: {
  ...cfg,
  hay_avisos: paraAvisar.length > 0,
  avisar: paraAvisar,
  nuevas: nuevas.length,
  resumen: {
    total_semana: semana.length,
    media,
    estrellas,
    por_sitio: porSitio,
    negativas: quejas.length,
    positivas: semana.filter((r) => r.sentimiento === 'positiva').length,
    neutras: semana.filter((r) => r.sentimiento === 'neutra').length,
    temas,
    tendencia,
  },
  mejores: semana.filter((r) => r.sentimiento === 'positiva').slice(0, 3),
  peores: quejas.slice(0, 5),
} }];

// Aviso inmediato: ha entrado una reseña negativa y conviene contestarla hoy.
const d = $input.first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const VERDE = '#235b54'; const TINTA = '#35322c'; const SUAVE = '#6e6a61';
const REGLA = '#e7e4dc'; const PAPEL = '#f4f3ef'; const ALERTA = '#8f2f24';
const estrellas = (n) => (n === null || n === undefined ? '—' : '★'.repeat(n) + '☆'.repeat(5 - n));
const cuando = (f) => new Date(f).toLocaleString('es-ES', { dateStyle: 'short', timeStyle: 'short' });

const tarjetas = d.avisar.map((r) => `<div style="border-left:3px solid ${ALERTA};background:#f8eae7;padding:14px 16px;border-radius:0 8px 8px 0;margin-bottom:12px">
<div style="font-size:12px;color:${SUAVE}">${esc(r.sitio)} · ${esc(r.autor)} · ${cuando(r.fecha)}</div>
<div style="font-size:15px;color:${ALERTA};letter-spacing:2px;padding:4px 0">${estrellas(r.puntuacion)}</div>
<div style="font-size:14px;color:${TINTA};line-height:1.5">${esc(r.texto)}</div>
${r.url ? `<div style="padding-top:8px"><a href="${esc(r.url)}" style="font-size:13px;color:${VERDE}">Ver y contestar</a></div>` : ''}
</div>`).join('');

const email_html = `<!doctype html><html><body style="margin:0;background:${PAPEL};font-family:Arial,Helvetica,sans-serif;color:${TINTA}">
<table width="100%" cellspacing="0"><tr><td align="center" style="padding:24px">
<table width="640" cellspacing="0" style="background:#fff;border-radius:12px"><tr><td style="padding:28px">
<div style="font-family:Georgia,'Times New Roman',serif;font-size:22px;color:${ALERTA}">${d.avisar.length === 1 ? 'Reseña negativa' : `${d.avisar.length} reseñas negativas`} · ${esc(d.tienda)}</div>
<div style="font-size:12px;color:${SUAVE};padding:2px 0 16px;border-bottom:1px solid ${REGLA}">${new Date(d.ahora).toLocaleString('es-ES', { dateStyle: 'long', timeStyle: 'short' })}</div>
<p style="font-size:14px;color:${TINTA};margin:16px 0">Aquí tienes cada reseña completa y el enlace para contestarla.</p>
${tarjetas}
<div style="border-top:1px solid ${REGLA};margin-top:16px;padding-top:12px;font-size:11px;color:${SUAVE}">Denoro Automations</div>
</td></tr></table></td></tr></table></body></html>`;

const telegram = `⚠️ <b>${d.avisar.length === 1 ? 'Reseña negativa' : `${d.avisar.length} reseñas negativas`} · ${d.tienda}</b>\n\n` +
  d.avisar.slice(0, 3).map((r) => `${estrellas(r.puntuacion)} <b>${r.sitio}</b> · ${r.autor}\n<i>${String(r.texto).slice(0, 180)}${r.texto.length > 180 ? '…' : ''}</i>` +
    (r.url ? `\n<a href="${r.url}">Contestar</a>` : '')).join('\n\n') +
  (d.avisar.length > 3 ? `\n\n…y ${d.avisar.length - 3} más en el email.` : '');

return [{ json: { ...d, asunto: `⚠️ Denoro · ${d.avisar.length} reseña(s) negativa(s) en ${d.tienda}`, email_html, telegram } }];

// Resumen semanal: nota media, tendencia, de qué se queja la gente y qué reseñas destacan.
const d = $input.first().json;
const r = d.resumen;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const VERDE = '#235b54'; const TINTA = '#35322c'; const SUAVE = '#6e6a61';
const REGLA = '#e7e4dc'; const PAPEL = '#f4f3ef'; const ALERTA = '#8f2f24'; const OK = '#2c5f3c';
const h3 = (t) => `<h3 style="font-family:Georgia,'Times New Roman',serif;font-size:17px;color:${VERDE};margin:24px 0 8px;font-weight:normal">${t}</h3>`;
const cifra = (n, t, color) => `<td width="25%" style="padding:0 8px"><div style="font-family:Georgia,serif;font-size:30px;color:${color || VERDE};line-height:1">${n}</div><div style="font-size:12px;color:${SUAVE};padding-top:2px">${t}</div></td>`;
const es = (n) => (n === null || n === undefined ? '—' : String(n).replace('.', ','));
const estrellasTxt = (n) => (n === null || n === undefined ? '—' : '★'.repeat(n) + '☆'.repeat(5 - n));

const maxBarra = Math.max(1, ...r.estrellas.map((e) => e.total));
const barras = [...r.estrellas].reverse().map((e) => `<tr>
<td width="60" style="font-size:13px;color:${SUAVE};padding:3px 0">${e.estrellas} ★</td>
<td style="padding:3px 0"><div style="background:${e.estrellas < d.umbral_negativa ? ALERTA : (e.estrellas === d.umbral_negativa ? '#8a857a' : VERDE)};height:10px;border-radius:5px;width:${Math.round((e.total / maxBarra) * 100)}%;min-width:${e.total ? '6px' : '0'}"></div></td>
<td width="40" align="right" style="font-size:13px;color:${TINTA};padding:3px 0">${e.total}</td></tr>`).join('');

const temas = r.temas.length ? `<table width="100%" cellspacing="0">${r.temas.map((t) => `<tr>
<td style="font-size:14px;color:${TINTA};padding:5px 0;border-bottom:1px solid ${REGLA}">${esc(t.tema)}</td>
<td align="right" style="font-size:14px;color:${ALERTA};padding:5px 0;border-bottom:1px solid ${REGLA}">${t.total}</td></tr>`).join('')}</table>`
  : `<p style="font-size:14px;color:${SUAVE};margin:0">Ninguna queja esta semana.</p>`;

const cita = (x, color) => `<div style="border-left:3px solid ${color};padding:10px 14px;margin-bottom:10px">
<div style="font-size:12px;color:${SUAVE}">${esc(x.sitio)} · ${esc(x.autor)} · <span style="letter-spacing:2px;color:${color}">${estrellasTxt(x.puntuacion)}</span></div>
<div style="font-size:14px;color:${TINTA};line-height:1.5;padding-top:4px">${esc(String(x.texto).slice(0, 240))}${x.texto.length > 240 ? '…' : ''}</div></div>`;

const flecha = r.tendencia ? (r.tendencia.media > 0 ? `<span style="color:${OK}">▲ +${es(r.tendencia.media)}</span>`
  : (r.tendencia.media < 0 ? `<span style="color:${ALERTA}">▼ −${es(Math.abs(r.tendencia.media))}</span>` : '=')) : '';

const email_html = `<!doctype html><html><body style="margin:0;background:${PAPEL};font-family:Arial,Helvetica,sans-serif;color:${TINTA}">
<table width="100%" cellspacing="0"><tr><td align="center" style="padding:24px">
<table width="680" cellspacing="0" style="background:#fff;border-radius:12px"><tr><td style="padding:28px">
<div style="font-family:Georgia,'Times New Roman',serif;font-size:22px;color:${VERDE}">Reseñas de la semana · ${esc(d.tienda)}</div>
<div style="font-size:12px;color:${SUAVE};padding:2px 0 12px;border-bottom:1px solid ${REGLA}">${new Date(d.ahora).toLocaleDateString('es-ES', { dateStyle: 'long' })} · ${Object.entries(r.por_sitio).map(([s, n]) => `${esc(s)}: ${n}`).join(' · ') || 'sin reseñas'}</div>
<table width="100%" cellspacing="0" style="margin:4px 0 8px"><tr>
${cifra(es(r.media), `nota media ${flecha}`)}${cifra(r.total_semana, 'reseñas')}${cifra(r.negativas, 'quejas', r.negativas ? ALERTA : null)}${cifra(r.positivas, 'elogios', r.positivas ? OK : null)}
</tr></table>
${h3('Reparto de estrellas')}
<table width="100%" cellspacing="0">${barras}</table>
${h3('De qué se queja la gente')}
${temas}
${d.peores.length ? `${h3('Para contestar')}${d.peores.map((x) => cita(x, ALERTA)).join('')}` : ''}
${d.mejores.length ? `${h3('Lo que mejor funciona')}${d.mejores.map((x) => cita(x, OK)).join('')}` : ''}
<div style="border-top:1px solid ${REGLA};margin-top:24px;padding-top:12px;font-size:11px;color:${SUAVE}">Denoro Automations</div>
</td></tr></table></td></tr></table></body></html>`;

const telegram = `⭐ <b>Reseñas de la semana · ${d.tienda}</b>\n` +
  `<b>Nota media:</b> ${es(r.media)}${r.tendencia ? ` (${r.tendencia.media > 0 ? '+' : '−'}${es(Math.abs(r.tendencia.media))} vs semana anterior)` : ''}\n` +
  `<b>Reseñas:</b> ${r.total_semana} · <b>Quejas:</b> ${r.negativas} · <b>Elogios:</b> ${r.positivas}` +
  (r.temas.length ? `\n<b>Motivo principal de queja:</b> ${r.temas[0].tema} (${r.temas[0].total})` : '');

return [{ json: { ...d, asunto: `Denoro · Reseñas de ${d.tienda}: media ${es(r.media)} (${r.total_semana} esta semana)`, email_html, telegram } }];

// (Se añade a cada automatización en su versión «para un cliente»)
// Guarda en denoro_estado lo que ha pasado en esta ejecución, para enseñarlo en el panel.
const d = $input.first()?.json || {};
const cfg = $('Configuración').first().json;
const txt = (s) => String(s || '').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
const titulo = txt(d.asunto).replace(/^[^\p{L}\p{N}]*Denoro · /u, '').replace(/^[^\p{L}\p{N}]+/u, '');
return [{ json: {
  clave: cfg.__clave, token: cfg.__token, snapshot: '',
  resumen: JSON.stringify({
    ultima: new Date().toISOString(), ok: true, modo: cfg.modo || null,
    titulo: (titulo || "Sin reseñas negativas nuevas").slice(0, 200),
    texto: txt(d.telegram).slice(0, 1500),
    avisado: Boolean(d.asunto && (d.enviar_email || d.enviar_telegram)),
    demo: [cfg.fuente, cfg.destino].includes('demo'),
  }),
} }];
